/** The FabricScan AI logo (web/public/logo.png, generated by scripts/make_web_images.py). */
export function LogoMark({ className = "size-9" }: { className?: string }) {
  return <img src="/logo.png" alt="" width={256} height={256} className={`${className} object-contain`} draggable={false} />;
}

export function Logo() {
  return (
    <span className="flex items-center gap-2">
      <LogoMark />
      <span className="font-display text-lg font-bold tracking-tight text-ink">
        FabricScan <span className="text-brand">AI</span>
      </span>
    </span>
  );
}
